  '\\nFlux Forms\\\'s payment table was not found. Is Flux Forms installed?\\n' => '\\nلم يتم العثور على جدول الدفع الخاص بـFlux Forms. هل تم تثبيت Flux Forms؟\\n',
  '\\nImporting...\\n' => '\\nجارٍ الاستيراد...\\n',
  '\\nImport now\\n' => '\\nاستيراد الآن\\n',
  '\\nLast run%1$s:%2$spayments checked,%3$simported.\\n' => '\\nآخر تشغيل%1$s: تم فحص دفعات%2$s، واستيراد%3$s.\\n',
