  '\\nColours and corners\\n' => '\\nالألوان والزوايا\\n',
  '\\nUsed by the form and the payment options. Empty fields follow the theme.\\n' => '\\nيتم استخدامه بواسطة النموذج وخيارات الدفع. الحقول الفارغة تتبع السمة.\\n',
