  '\\nLink a form to a donation type\\n' => '\\nربط نموذج بنوع التبرع\\n',
  '\\nValue "slug=form id", e.g. "fidan=3". Forms:%s\\n' => '\\nالقيمة "slug=form id"، على سبيل المثال: "فيدان=3". النماذج:%s\\n',
