  'Info' => 'معلومات',
  '%1$d OK · %2$d warnings · %3$d errors' => '%1$dموافق · تحذيرات%2$d· أخطاء%3$d',
  'Check again' => 'تحقق مرة أخرى',
  'Show only these (click again to show all)' => 'إظهار هذه فقط (انقر مرة أخرى لإظهار الكل)',
