  '%1$s was refunded, then iyzico stopped: %2$s' => '\\n تم استرداد أموال%1$s، ثم توقف iyzico:%2$s\\n',
  'Recurring donation not found.' => '\\nلم يتم العثور على التبرع المتكرر.\\n',
