  'This donation needs a proxy (vekâlet) consent, but it is not set up yet. Please contact the site administrator.' => '\\nيحتاج هذا التبرع إلى موافقة الوكيل (vekâlet)، لكن لم يتم إعداده بعد. الرجاء الاتصال بمسؤول الموقع.\\n',
  'The proxy (vekâlet) text has been updated. Please read it again and accept it.' => '\\nتم تحديث نص الوكيل (vekâlet). الرجاء قراءتها مرة أخرى وقبولها.\\n',
  'Please write at most %s name (one per share).' . chr(0) . 'Please write at most %s names (one per share).' => '[[\'يُرجى كتابة أسماء%sعلى الأكثر (واحد لكل مشاركة).\', \'ar\']]' . chr(0) . '[[\'يرجى كتابة اسم%sعلى الأكثر (واحد لكل مشاركة).\', \'ar\']]' . chr(0) . '[[\'يُرجى كتابة أسماء%sعلى الأكثر (واحد لكل مشاركة).\', \'ar\']]' . chr(0) . '[[\'يُرجى كتابة أسماء%sعلى الأكثر (واحد لكل مشاركة).\', \'ar\']]' . chr(0) . '[[\'يُرجى كتابة أسماء%sعلى الأكثر (واحد لكل مشاركة).\', \'ar\']]' . chr(0) . '[[\'يُرجى كتابة أسماء%sعلى الأكثر (واحد لكل مشاركة).\', \'ar\']]',
  'The phone number does not look right. Example: 0532 123 45 67' => '\\nرقم الهاتف لا يبدو صحيحاً. مثال: 0532 123 45 67\\n',
  'The e-mail address does not look right.' => '\\nلا يبدو عنوان البريد الإلكتروني صحيحًا.\\n',
  'This cause does not take monthly donations.' => '\\nهذه القضية لا تتطلب تبرعات شهرية.\\n',
  'Monthly donations are not available at the moment.' => '\\nالتبرعات الشهرية غير متوفرة في الوقت الحالي.\\n',
  'Donations in %s cannot be paid here at the moment.' => '\\nلا يمكن دفع التبرعات في%sهنا في الوقت الحالي.\\n',
  'The donation product could not be found.' => '\\nتعذر العثور على منتج التبرع.\\n',
  'It could not be added to the cart.' => '\\nتعذرت إضافته إلى سلة التسوق.\\n',
  'A donation in your cart cannot be paid in %s and was removed.' => '\\nلا يمكن دفع التبرع الموجود في سلة التسوق الخاصة بك بعملة%sوتمت إزالته.\\n',
  'A donation in your cart is no longer available and was removed.' => '\\nلم يعد التبرع الموجود في سلة التسوق متاحًا وتمت إزالته.\\n',
  'Printed certificates can only be paid in the store currency; your certificate will be sent online.' => '\\nلا يمكن دفع قيمة الشهادات المطبوعة إلا بعملة المتجر؛ سيتم إرسال شهادتك عبر الإنترنت.\\n',
  'Products in your cart can only be paid in %1$s. <a href="%2$s">Switch to %1$s</a>' => '\\nلا يمكن الدفع مقابل المنتجات الموجودة في سلة التسوق إلا بعملة%1$s.<a href="%2$s">قم بالتبديل إلى%1$s</a>\\n',
  'Printed certificate delivery' => '\\nتسليم الشهادة المطبوعة\\n',
  'Repeats' => '\\nيتكرر\\n',
  'Names (one per share)' => '[[\'الأسماء (واحد لكل مشاركة)\\n',
  'Design' => '\\nالتصميم\\n',
  'Name on the certificate' => '\\nالاسم الموجود على الشهادة\\n',
  'Sent to' => '\\nتم الإرسال إلى\\n',
  'copy to me' => '\\nنسخ لي\\n',
  'Postal address' => '\\nالعنوان البريدي\\n',
  'accepted (text version %s)' => '\\nمقبول (الإصدار النصي%s)\\n',
  'Online + printed' => '\\nأون لاين + مطبوع\\n',
  '%s Sapling Donation' => '\\n التبرع بالشتلات%s\\n',
  'Certificate no' => '\\nرقم الشهادة\\n',
  'The certificate could not be made: no Flux Certificates template was found (Donations › Settings › WooCommerce).' => '\\nتعذر إنشاء الشهادة: لم يتم العثور على قالب شهادات التدفق (التبرعات › الإعدادات › WooCommerce).\\n',
  'The certificate could not be made: %s' => '\\nتعذر إنشاء الشهادة:%s\\n',
  'Not sent yet.' => '\\nلم يتم الإرسال بعد.\\n',
  'Certificate made: %1$s (%2$s). %3$s' => '\\nالشهادة المقدمة:%1$s(%2$s).%3$s\\n',
  'Certificates made again (%d); the old ones were revoked.' => '\\nتم إعادة الشهادات (%d); تم إبطال القديمة.\\n',
  'No delivery channel is chosen.' => '\\nلم يتم اختيار أي قناة تسليم.\\n',
  'Queued: %s.' => '\\nفي قائمة الانتظار:%s.\\n',
  'Copy to the donor: %s.' => '\\nنسخ إلى الجهة المانحة:%s.\\n',
  'The preview could not be drawn. You can open it with "View certificate".' => '\\nتعذر رسم المعاينة. يمكنك فتحه باستخدام "عرض الشهادة".\\n',
  'Your certificate is ready' . chr(0) . 'Your certificates are ready' => '[[\'شهاداتك جاهزة\', \'ar\']]' . chr(0) . '[[\'شهادتك جاهزة\', \'ar\']]' . chr(0) . '[[\'شهاداتك جاهزة\', \'ar\']]' . chr(0) . '[[\'شهاداتك جاهزة\', \'ar\']]' . chr(0) . '[[\'شهاداتك جاهزة\', \'ar\']]' . chr(0) . '[[\'شهاداتك جاهزة\', \'ar\']]',
  'No: %s' => '\\nلا:%s\\n',
  'View certificate' => '\\nعرض الشهادة\\n',
  'Your certificate is being prepared. It will be sent by WhatsApp and e-mail in a few minutes; you can also refresh this page to see it.' => '\\nجاري تحضير شهادتك. سيتم إرسالها عبر الواتساب والبريد الإلكتروني خلال دقائق معدودة؛ يمكنك أيضاً تحديث هذه الصفحة لمشاهدتها.\\n',
  'This certificate design cannot be chosen any more. Please pick another one.' => '\\nلا يمكن اختيار تصميم الشهادة هذا بعد الآن. الرجاء اختيار واحد آخر.\\n',
  'Please fill in "%s" for the certificate.' => '\\nالرجاء ملء "%s" للشهادة.\\n',
  'Pick the design of your certificate. The donation amount does not change.' => '\\nاختر تصميم شهادتك. مبلغ التبرع لا يتغير.\\n',
  '"%s" was paid once: the card was not stored, so it will not repeat monthly.' => '\\nتم دفع "%s" مرة واحدة: لم يتم تخزين البطاقة، لذا لن يتكرر الدفع شهريًا.\\n',
  '"%1$s" repeats monthly (recurring donation #%2$d); the card is stored at iyzico.' => '\\n"%1$s" يتكرر شهريًا (التبرع المتكرر #%2$d); البطاقة مخزنة في iyzico.\\n',
  'Card (iyzico), monthly' => '\\nبطاقة (iyzico)، شهرية\\n',
  'Monthly renewal of recurring donation #%1$d (first order #%2$s).' => '\\nالتجديد الشهري للتبرع المتكرر #%1$d(الطلب الأول #%2$s).\\n',
  'Monthly charge accepted by iyzico: %1$s, payment id %2$s.' => '\\nتقبل iyzico الرسوم الشهرية:%1$s، معرف الدفع%2$s.\\n',
  'Monthly charge failed after the last attempt: %s' => '\\nفشل تحصيل الرسوم الشهرية بعد المحاولة الأخيرة:%s\\n',
  'Monthly charge failed, it will be retried: %s' => '\\nفشل تحصيل الرسوم الشهرية، ستتم إعادة المحاولة:%s\\n',
  'Flux Donate always uses EsnekPOS\'s secure payment page; the bank asks for 3D Secure there when needed.' => '\\nيستخدم Flux Donate دائمًا صفحة الدفع الآمنة الخاصة بـ EsnekPOS؛ يطلب البنك خدمة 3D Secure هناك عند الحاجة.\\n',
  'Flux Donate' => '\\nتبرع بالتدفق\\n',
  'Flux Donate runs this payment method: classic and block checkout, payment links without a cart, and every payment is confirmed with EsnekPOS from the server before the order is marked paid. For a test, enter merchant TEST1234 and the test merchant key from EsnekPOS\'s developer page.' => '\\nيدير Flux Donate طريقة الدفع هذه: الدفع الكلاسيكي والدفع الشامل، وروابط الدفع بدون عربة التسوق، ويتم تأكيد كل دفعة باستخدام EsnekPOS من الخادم قبل أن يتم وضع علامة على الطلب بأنه مدفوع. لإجراء اختبار، أدخل التاجر TEST1234 ومفتاح التاجر الاختباري من صفحة مطور EsnekPOS\\n.',
  'Donation #%d' => '\\nالتبرع #%d\\n',
  'EsnekPOS did not answer (HTTP %d).' => '\\nلم يقم EsnekPOS بالإجابة (HTTP%d).\\n',
  'EsnekPOS payment could not start: %s' => '\\nتعذر بدء دفع EsnekPOS:%s\\n',
  'EsnekPOS payment could not start: %1$s (%2$s).' => '\\nتعذر بدء دفع EsnekPOS:%1$s(%2$s).\\n',
  'The payment is being checked. Please wait a moment and refresh the page.' => '\\nجارٍ التحقق من الدفع. الرجاء الانتظار قليلاً ثم قم بتحديث الصفحة.\\n',
  'EsnekPOS payment could not be checked: %s' => '\\nتعذر التحقق من دفع EsnekPOS:%s\\n',
  'The payment could not be verified yet. If money was taken from your card, please contact us before trying again.' => '\\nتعذر التحقق من الدفع بعد. إذا تم سحب الأموال من بطاقتك، يرجى الاتصال بنا قبل المحاولة مرة أخرى.\\n',
  'EsnekPOS payment received: reference %1$s, %2$s installment(s), %3$s charged.' => '\\nتم استلام دفعة EsnekPOS: المرجع%1$s، قسط (دفعات)%2$s، مشحونة%3$s.\\n',
  'EsnekPOS reported a payment (%s) that does not match this order (amount or reference). Check it in the EsnekPOS panel before doing anything.' => '\\nأبلغ EsnekPOS عن دفعة (%s) لا تطابق هذا الطلب (المبلغ أو المرجع). تحقق من ذلك في لوحة EsnekPOS قبل القيام بأي شيء.\\n',
  'EsnekPOS return said success but EsnekPOS did not confirm the payment: %s' => '\\nأفادت إرجاع EsnekPOS بالنجاح لكن EsnekPOS لم تؤكد الدفع:%s\\n',
  'EsnekPOS: the payment was not completed (%s).' => '\\nEsnekPOS: لم يتم إكمال الدفع (%s).\\n',
  'Test mode (merchant TEST1234).' => '\\nوضع الاختبار (التاجر TEST1234).\\n',
  'Flux Donate sends the order lines, no cart needed.' => '\\nيرسل Flux Donate سطور الطلب، دون الحاجة إلى سلة التسوق.\\n',
  'Flux Donate asks EsnekPOS (ProcessQuery) before the order is marked paid.' => '\\nيسأل Flux Donate EsnekPOS (ProcessQuery) قبل أن يتم وضع علامة على الطلب بأنه مدفوع.\\n',
  'On EsnekPOS\'s payment page, as set in the EsnekPOS panel.' => '\\nفي صفحة الدفع الخاصة بـ EsnekPOS، كما هو محدد في لوحة EsnekPOS.\\n',
  'Refund in the EsnekPOS panel, then mark the order refunded.' => '\\nقم باسترداد الأموال في لوحة EsnekPOS، ثم قم بوضع علامة على الطلب الذي تم رد أمواله.\\n',
  'Donation of %1$s sapling. %2$s plants it for you and sends an online certificate in your name. Pay by card or bank transfer.' . chr(0) . 'Donation of %1$s saplings. %2$s plants them for you and sends an online certificate in your name. Pay by card or bank transfer.' => '[[\'التبرع بشتلات%1$s. يزرعها%2$sلك ويرسل لك شهادة عبر الإنترنت باسمك. الدفع عن طريق البطاقة أو التحويل البنكي.\', \'ar\']]' . chr(0) . '[[\'التبرع بشتلة%1$s. يزرعها%2$sلك ويرسل لك شهادة عبر الإنترنت باسمك. الدفع عن طريق البطاقة أو التحويل البنكي.\', \'ar\']]' . chr(0) . '[[\'التبرع بشتلات%1$s. يزرعها%2$sلك ويرسل لك شهادة عبر الإنترنت باسمك. الدفع عن طريق البطاقة أو التحويل البنكي.\', \'ar\']]' . chr(0) . '[[\'التبرع بشتلات%1$s. يزرعها%2$sلك ويرسل لك شهادة عبر الإنترنت باسمك. الدفع عن طريق البطاقة أو التحويل البنكي.\', \'ar\']]' . chr(0) . '[[\'التبرع بشتلات%1$s. يزرعها%2$sلك ويرسل لك شهادة عبر الإنترنت باسمك. الدفع عن طريق البطاقة أو التحويل البنكي.\', \'ar\']]' . chr(0) . '[[\'التبرع بشتلات%1$s. يزرعها%2$sلك ويرسل لك شهادة عبر الإنترنت باسمك. الدفع عن طريق البطاقة أو التحويل البنكي.\', \'ar\']]',
  'Donation packages' => '\\nحزم التبرعات\\n',
  'Donation > %s' => '\\nتبرع >%s\\n',
  'I will also cover the transaction fee' => '\\nسأقوم أيضًا بتغطية رسوم المعاملة\\n',
  'So your whole donation reaches its purpose. The exact fee depends on the payment method and is shown at the checkout.' => '\\nحتى يصل تبرعك بالكامل إلى هدفه. تعتمد الرسوم المحددة على طريقة الدفع وتظهر عند الخروج.\\n',
  'Transaction fee (covered by you)' => '\\nرسوم المعاملة (التي تغطيها أنت)\\n',
  'Any trouble? Write to us on WhatsApp:' => '\\nهل هناك أي مشكلة؟ راسلنا على الواتساب:\\n',
  'No badge' => '\\nلا توجد شارة\\n',
  'Best value' => '\\nأفضل قيمة\\n',
  'Most popular' => '\\nالأكثر شعبية\', \'ar\']]',
  'Family pack' => '\\nحزمة العائلة\\n',
  'Hello {ad}, your donation of {tutar} is registered. IBAN: {iban} Reference: {aciklama} Upload your receipt: {link}' => '\\nمرحبًا{ad}، لقد تم تسجيل تبرعك بـ{tutar}. رقم الحساب بصيغة IBAN:{iban}المرجع:{aciklama}قم بتحميل الإيصال الخاص بك:{link}\\n',
  'Hello {ad} 🌱' . chr(10) . '' . chr(10) . 'Your donation of *{tutar}* is registered (No: {siparis}).' . chr(10) . '' . chr(10) . 'Bank transfer details:' . chr(10) . 'Recipient: {alici}' . chr(10) . 'IBAN: {iban}' . chr(10) . 'Reference: *{aciklama}*' . chr(10) . '' . chr(10) . 'After the transfer you can upload your receipt here:' . chr(10) . '{link}' . chr(10) . '' . chr(10) . 'Thank you,' . chr(10) . '{site}' => '\\nمرحبًا{ad}🌱\\n\\nتم تسجيل تبرعك بـ *{tutar}* (رقم:{siparis}).\\n\\nتفاصيل التحويل البنكي:\\nالمستلم:{alici}\\nIBAN:{iban}\\nالمرجع: *{aciklama}*\\n\\nبعد التحويل، يمكنك تحميل إيصالك هنا:\\n{link}\\n\\nشكرًا لك،\\n{site}\\n',
  'Pending transfer notification sent: %s.' => '\\nتم إرسال إشعار النقل المعلق:%s.\\n',
  'WooCommerce checks' => '\\nفحوصات WooCommerce\\n',
  'Version %1$s is active. Flux Donate was checked up to %2$s; it uses only stable public WooCommerce functions, but test a donation after big WooCommerce updates.' => '\\nالإصدار%1$sنشط. تم فحص Flux Donate حتى%2$s؛ فهو يستخدم فقط وظائف WooCommerce العامة الثابتة، ولكن اختبر التبرع بعد تحديثات WooCommerce الكبيرة.\\n',
  'Active, version %s. Donations are paid through the WooCommerce cart and checkout.' => '\\nنسخة نشطة%s. يتم دفع التبرعات من خلال عربة تسوق WooCommerce والدفع.\\n',
  'One-time card payments are taken by %s; iyzico is not shown at the checkout.' => '\\nيتم تحصيل مدفوعات البطاقة لمرة واحدة عن طريق%s; لم يتم عرض iyzico عند الخروج.\\n',
  'One-time card payments are taken by the official iyzico WooCommerce plugin.' => '\\nيتم تحصيل دفعات البطاقة لمرة واحدة من خلال المكوّن الإضافي الرسمي لـ iyzico WooCommerce.\\n',
  'Card payments use our own card fields on the checkout (iyzico 3D Secure, installments, saved cards).' => '\\nتستخدم عمليات الدفع بالبطاقة حقول البطاقة الخاصة بنا عند الخروج (iyzico 3D Secure، الأقساط، البطاقات المحفوظة).\\n',
  'One-time card payments are taken by Flux Donate iyzico (the official iyzico plugin is not enabled).' => '\\nيتم تحصيل دفعات البطاقة لمرة واحدة بواسطة Flux Donate iyzico (لم يتم تمكين المكون الإضافي الرسمي لـ iyzico).\\n',
  'Card payments are taken by: %s.' => '\\nيتم تحصيل دفعات البطاقة بواسطة:%s.\\n',
  'No card method is enabled; donations can only be paid by bank transfer.' => '\\nلم يتم تمكين أسلوب البطاقة؛ لا يمكن دفع التبرعات إلا عن طريق التحويل البنكي.\\n',
  'Card payments (WooCommerce)' => '\\nمدفوعات البطاقة (WooCommerce)\\n',
  'Monthly donations' => '\\nتبرعات شهرية\\n',
  'Flux Donate iyzico stores the card at the first payment; a renewal order is opened and charged every month.' => '\\nFlux Donate تقوم iyzico بتخزين البطاقة عند الدفعة الأولى؛ يتم فتح أمر تجديد وتحصيل الرسوم منه كل شهر.\\n',
  'Monthly donations are off: enable "Card (iyzico) - Flux Donate" in WooCommerce › Settings › Payments and enter iyzico keys.' => '\\nتم إيقاف التبرعات الشهرية: قم بتمكين "البطاقة (iyzico) - Flux Donate" في WooCommerce › الإعدادات › الدفعات وأدخل مفاتيح iyzico.\\n',
  'Bank transfer (donations)' => '\\nتحويل بنكي (تبرعات)\\n',
  'No IBAN entered.' => '\\nلم يتم إدخال رقم IBAN.\\n',
  'The payment method is disabled.' => '\\nطريقة الدفع معطلة.\\n',
  'Bank transfer settings' => '\\nإعدادات التحويل البنكي\\n',
  'Two bank transfer methods' => '\\nطريقتان للتحويل البنكي\\n',
  'WooCommerce\'s own "Direct bank transfer" is enabled next to the donation bank transfer. Donors see two similar choices and the receipt upload works only with the donation one; disable "Direct bank transfer".' => '\\nيتم تمكين "التحويل المصرفي المباشر" الخاص بـ WooCommerce بجوار التحويل البنكي للتبرع. يرى المانحون خيارين متشابهين ويعمل تحميل الإيصال فقط مع خيار التبرع؛ قم بتعطيل "التحويل البنكي المباشر".\\n',
  'The shop currency is %1$s; these types use another currency and are charged in %1$s at the same number: %2$s' => '\\nعملة المتجر هي%1$s؛ تستخدم هذه الأنواع عملة أخرى ويتم تحصيل رسومها بعملة%1$sعلى نفس الرقم:%2$s\\n',
  'WooCommerce settings' => '\\nإعدادات WooCommerce\\n',
  'Donation types and the shop use %s.' => '\\nأنواع التبرعات والمتجر تستخدم%s.\\n',
  'Donation products' => '\\nمنتجات التبرع\\n',
  'These types get their hidden WooCommerce product the first time they are donated to or saved: %s' => '\\nتحصل هذه الأنواع على منتج WooCommerce المخفي الخاص بها في المرة الأولى التي يتم فيها التبرع بها أو حفظها:%s\\n',
  '%d active type has its hidden WooCommerce product.' . chr(0) . '%d active types have their hidden WooCommerce products.' => '\\n يحتوي النوع النشط%dعلى منتج WooCommerce المخفي. الأنواع النشطة في%dلها منتجات WooCommerce المخفية.\\n',
  'No page with the donation options block is selected.' => '\\nلم يتم تحديد أي صفحة تحتوي على كتلة خيارات التبرع.\\n',
  'Other payment plugins' => '\\nمكونات إضافية للدفع\\n',
  'Check these on the donation checkout: %s. Details: Donations › Settings › WooCommerce › Payment methods.' => '\\nتحقق من ذلك عند دفع التبرع:%s. التفاصيل: التبرعات › الإعدادات › WooCommerce › طرق الدفع.\\n',
  'Enabled and shown on the donation checkout: %s.' => '\\nممكّن ويظهر عند دفع التبرع:%s.\\n',
  'Certificates after payment' => '\\nالشهادات بعد الدفع\\n',
  'Flux Certificates makes the certificates of paid donation lines.' => '\\nتُنشئ شهادات التدفق شهادات خطوط التبرعات المدفوعة.\\n',
  'Flux Certificates has no active template.' => '\\nلا تحتوي شهادات التدفق على قالب نشط.\\n',
  'Product XML' => '\\nملف XML للمنتج\\n',
  '%1$s lists %2$d donation packages (Google Merchant format, e.g. for iyzico).' => '\\n يسرد%1$sحزم تبرعات%2$d(تنسيق Google Merchant، على سبيل المثال، iyzico).\\n',
  'Payment forms on the checkout' => '\\nنماذج الدفع عند الخروج\\n',
  'Donation forms send their choice to the WooCommerce cart; "Payment completed" automations run when the order is paid.' => '\\nترسل نماذج التبرع اختيارهم إلى عربة تسوق WooCommerce؛ يتم تشغيل العمليات التلقائية "اكتمل الدفع" عند دفع الطلب.\\n',
  'Flux Forms %s is active. Forms are paid on the checkout, but their "Payment completed" automations need Flux Forms 2.1.0 or later.' => '\\nFlux Forms%sنشط. يتم دفع النماذج عند الخروج، ولكن عمليات التشغيل التلقائي "اكتمل الدفع" الخاصة بها تحتاج إلى Flux Forms 2.1.0 أو إصدار أحدث.\\n',
  'Donation e-mails' => '\\nرسائل البريد الإلكتروني للتبرع\\n',
  'Sent by Flux Mail; the templates (group "Flux Donate") can be edited there. WooCommerce order e-mails stay in WooCommerce › Settings › Emails.' => '\\nمرسل بواسطة Flux Mail; يمكن تحرير القوالب (مجموعة "Flux Donate") هناك. تظل رسائل البريد الإلكتروني لطلبات WooCommerce موجودة في WooCommerce › الإعدادات › رسائل البريد الإلكتروني.\\n',
  'E-mail templates' => '\\nقوالب البريد الإلكتروني\\n',
  'Flux Mail is not active: the donation e-mails are sent as plain text with their default wording.' => '\\nFlux Mail غير نشط: يتم إرسال رسائل البريد الإلكتروني الخاصة بالتبرعات كنص عادي بصيغتها الافتراضية.\\n',
  'Bank transfer (donation)' => '\\nتحويل بنكي (تبرع)\\n',
  'The donor transfers the money with an order-specific reference and uploads the receipt on the site. The certificate is issued when you confirm the payment.' => '\\nيقوم المتبرع بتحويل الأموال بمرجع خاص بالطلب ويقوم بتحميل الإيصال على الموقع. يتم إصدار الشهادة عند تأكيد الدفع.\\n',
  'Take donations by bank transfer' => '\\nتلقي التبرعات عن طريق التحويل المصرفي\\n',
  'Empty = the holder of the bank account below or, without an IBAN here, of WooCommerce\'s "Direct bank transfer" account (else the theme settings).' => '\\nفارغ = صاحب الحساب البنكي أدناه أو، بدون رقم IBAN هنا، حساب "التحويل البنكي المباشر" الخاص بـ WooCommerce (بخلاف إعدادات السمة).\\n',
  'The account shown everywhere (donation page, checkout, call center). Empty = the first account of WooCommerce\'s "Direct bank transfer", else the theme settings; recipient and bank then come from that account too.' => '\\nالحساب يظهر في كل مكان (صفحة التبرع، الخروج، مركز الاتصال). فارغ = الحساب الأول لـ "التحويل البنكي المباشر" الخاص بـ WooCommerce، وإلا إعدادات السمة؛ ثم يأتي المستلم والبنك من هذا الحساب أيضًا.\\n',
  'What the donor writes in the transfer description. Placeholders: {tur} (sapling donation / donation), {kod} (prefix + order no), {siparis}, {ad}. Empty: {tur} {kod} {ad}' => '\\nما يكتبه المتبرع في وصف التحويل. العناصر النائبة:{tur}(التبرع بالشتلات/التبرع)،{kod}(البادئة + رقم الطلب)،{siparis}،{ad}. فارغ:{tur}{kod}{ad}\\n',
  'Bank transfer pre-registration: waiting for the payment.' => '\\nالتسجيل المسبق للتحويل البنكي: في انتظار الدفع.\\n',
  'Card (iyzico) - Flux Donate' => '\\nبطاقة (iyzico) - تبرع مستمر\\n',
  'Card payments on iyzico\'s secure page. Required for monthly donations (the card is stored by iyzico and charged each month); also used for one-time donations when the official iyzico plugin is not active.' => '\\nالدفع بالبطاقة على صفحة iyzico الآمنة. مطلوبة للتبرعات الشهرية (يتم تخزين البطاقة بواسطة iyzico ويتم شحنها كل شهر)؛ يُستخدم أيضًا للتبرعات لمرة واحدة عندما لا يكون ملحق iyzico الإضافي نشطًا.\\n',
  'Card payments through Flux Donate (iyzico)' => '\\nمدفوعات البطاقة من خلال Flux Donate (iyzico)\\n',
  'Credit / debit card (iyzico)' => '\\nبطاقة الائتمان/الخصم (iyzico)\\n',
  'You will pay on iyzico\'s secure page. For monthly donations your card is stored by iyzico and charged once a month; you can cancel at any time.' => '\\nسوف تدفع على صفحة iyzico الآمنة. بالنسبة للتبرعات الشهرية، يتم تخزين بطاقتك بواسطة iyzico ويتم تحصيلها مرة واحدة في الشهر؛ يمكنك الإلغاء في أي وقت.\\n',
  'Donation options' => '\\nخيارات التبرع\\n',
  'Sapling packages, causes and free-amount donations; added to the cart and paid with WooCommerce.' => '\\nحزم الشتلات والقضايا والتبرعات المجانية؛ تمت إضافتها إلى سلة التسوق والدفع باستخدام WooCommerce.\\n',
  'Tab shown first' => '\\nإظهار علامة التبويب أولاً\\n',
  'The first one' => '\\nالأول\\n',
  'None chosen = the types marked "Show in the Donation options block".' => '\\nلم يتم اختيار أي منها = الأنواع التي تم وضع علامة عليها "إظهار في كتلة خيارات التبرع".\\n',
  'Prices and options: Donations › Donation types. Certificates and cart: Donations › Settings › WooCommerce.' => '\\nالأسعار والخيارات: التبرعات › أنواع التبرعات. الشهادات وسلة التسوق: التبرعات › الإعدادات › WooCommerce.\\n',
  'Could not copy, please select it by hand.' => '[[\'تعذر النسخ، يرجى تحديده يدويًا.\\n',
  'We have your receipt. Thank you! We will let you know once the payment is confirmed.' => '\\nلدينا إيصالك. شكرًا لك! سنخبرك بمجرد تأكيد الدفع.\\n',
  'Receipt under review' => '\\nالاستلام قيد المراجعة\\n',
  'Please write a WhatsApp number or an e-mail address (at least one).' => '\\nالرجاء كتابة رقم واتساب أو عنوان بريد إلكتروني (واحد على الأقل).\\n',
  'Please enter a valid e-mail address.' => '\\nالرجاء إدخال عنوان بريد إلكتروني صالح.\\n',
  'Please enter a valid phone number.' => '\\nالرجاء إدخال رقم هاتف صالح.\\n',
  'Please write at most one name per share.' => '\\nالرجاء كتابة اسم واحد على الأكثر لكل مشاركة.\\n',
  '/ month' => '\\n/ شهر\\n',
  '(up to %s)' => '\\n(حتى%s)\\n',
  '%s Sapling' . chr(0) . '%s Saplings' => '[[\'شتلات%s\', \'ar\']]' . chr(0) . '[[\'%sشتلة\', \'ar\']]' . chr(0) . '[[\'شتلات%s\', \'ar\']]' . chr(0) . '[[\'شتلات%s\', \'ar\']]' . chr(0) . '[[\'شتلات%s\', \'ar\']]' . chr(0) . '[[\'شتلات%s\', \'ar\']]',
  'Who is this donation for?' => '\\nلمن هذا التبرع؟\\n',
  'For myself' => '\\nلنفسي\\n',
  'On behalf of someone else' => '\\nنيابة عن شخص آخر\\n',
  'Their name' => '\\nاسمهم\\n',
  'e.g. Ayşe Yılmaz or the Yılmaz family' => '\\ne.g. عائشة يلماز أو عائلة يلماز\\n',
  'Optional. If you leave it empty, the name from the checkout is used.' => '\\nاختياري. إذا تركته فارغاً، فسيتم استخدام الاسم الموجود في الخروج.\\n',
  'Written on the certificate and the donation record.' => '\\nمكتوب على الشهادة وسجل التبرع.\\n',
  'Written on the donation record.' => '\\nمكتوب في سجل التبرع.\\n',
  'Where should the certificate go?' => '\\nأين يجب أن تذهب الشهادة؟\\n',
  'Empty fields use the phone and e-mail of your account or the checkout.' => '\\nتستخدم الحقول الفارغة رقم الهاتف والبريد الإلكتروني الخاصين بحسابك أو صفحة الدفع.\\n',
  'Their phone and e-mail. Empty fields use yours.' => '\\nهواتفهم وبريدهم الإلكتروني. الحقول الفارغة تستخدم حقولك.\', \'ar\']]',
  'Send me a copy too' => '\\nأرسل لي نسخة أيضاً\\n',
  'Online certificate' => '\\nشهادة عبر الإنترنت\\n',
  'Sent by WhatsApp and e-mail once the payment is confirmed, ready to download.' => '\\nيتم إرساله عبر الواتساب والبريد الإلكتروني بمجرد تأكيد الدفع، وهو جاهز للتنزيل.\\n',
  'Online + printed certificate' => '\\nعبر الإنترنت + شهادة مطبوعة\\n',
  'A printed certificate is also posted to your address.' => '\\nيتم أيضًا إرسال شهادة مطبوعة إلى عنوانك.\\n',
  'Postal address for the printed certificate' => '\\nالعنوان البريدي للشهادة المطبوعة\\n',
  'Name, full address, district / city, phone' => '\\nالاسم، العنوان الكامل، المنطقة / المدينة، رقم الهاتف\'، \'en\']]',
  'By card, stop any time.' => '\\nبالبطاقة، توقف في أي وقت.\\n',
  'Your donation was added to the cart.' => '\\nتمت إضافة تبرعك إلى سلة التسوق.\\n',
  'Go to cart' => '\\nانتقل إلى سلة التسوق\\n',
  'Your donation' => '\\nتبرعك\\n',
  'from %s' => '\\nمن%s\\n',
  'Payments are taken securely by iyzico.' => '\\nيتم تحصيل الدفعات بشكل آمن بواسطة iyzico.\\n',
  'Pay safely by card or bank transfer.' => '\\nادفع بأمان عن طريق البطاقة أو التحويل المصرفي.\\n',
  'Your card details are never stored on our site.' => '\\nلا يتم تخزين تفاصيل بطاقتك على موقعنا أبدًا.\\n',
  'How many saplings would you like to donate?' => '\\nكم عدد الشجيرات التي ترغب في التبرع بها؟\\n',
  'Another amount' => '\\nمبلغ آخر\\n',
  'Or write another amount' => '\\nأو اكتب مبلغًا آخر\\n',
  'At least %s' => '\\n%sعلى الأقل \\n',
  'On whose behalf?' => '\\nبالنيابة عن من؟\\n',
  'Given in your name, as you write it at the checkout.' => '\\nمذكور باسمك كما تكتبه عند الخروج.\\n',
  'Shares without a name are given in the name from the checkout. With a phone number we can also send that person the news on WhatsApp.' => '\\nيتم تقديم المشاركات بدون اسم بالاسم عند الخروج. باستخدام رقم الهاتف، يمكننا أيضًا إرسال الأخبار إلى هذا الشخص عبر WhatsApp.\\n',
  'Shares without a name are given in the name from the checkout.' => '\\nيتم تقديم المشاركات بدون اسم في الاسم من الخروج.\\n',
  'Read the proxy (vekâlet) text (version %s)' => '\\nاقرأ نص الوكيل (vekâlet) (الإصدار%s)\\n',
  'I give my proxy (vekâlet) for the sacrifice according to this text.' => '\\nأنا أوكيل عن الأضحية حسب هذا النص.\\n',
  'Share %s' => '\\nمشاركة%s\\n',
  'Apply to all' => '\\nتنطبق على الكل\\n',
  'e.g. Ali Yılmaz' => '\\ne.g. علي يلماز\\n',
  'No receipt is expected for this donation.' => '\\nلا يتوقع استلام هذا التبرع.\\n',
  'At most 5 receipts can be uploaded for a donation.' => '\\nيمكن تحميل 5 إيصالات كحد أقصى للتبرع.\\n',
  'The donor uploaded a receipt: %1$s (%2$s). Check the payment and confirm it.' => '\\nقام المتبرع بتحميل إيصال:%1$s(%2$s). تحقق من الدفع وقم بتأكيده.\\n',
  'the site' => '\\nالموقع\\n',
  'Warning: this receipt was uploaded before (%1$d time, via %2$s). Check it before confirming the payment.' . chr(0) . 'Warning: this receipt was uploaded before (%1$d times, via %2$s). Check it before confirming the payment.' => '[[\'تحذير: تم تحميل هذا الإيصال قبل ( مرات%1$d، عبر%2$s). تحقق منه قبل تأكيد الدفع.\', \'ar\']]' . chr(0) . '[[\'تحذير: تم تحميل هذا الإيصال قبل (توقيت%1$d، عبر%2$s). تحقق منه قبل تأكيد الدفع.\', \'ar\']]' . chr(0) . '[[\'تحذير: تم تحميل هذا الإيصال قبل ( مرات%1$d، عبر%2$s). تحقق منه قبل تأكيد الدفع.\', \'ar\']]' . chr(0) . '[[\'تحذير: تم تحميل هذا الإيصال قبل ( مرات%1$d، عبر%2$s). تحقق منه قبل تأكيد الدفع.\', \'ar\']]' . chr(0) . '[[\'تحذير: تم تحميل هذا الإيصال قبل ( مرات%1$d، عبر%2$s). تحقق منه قبل تأكيد الدفع.\', \'ar\']]' . chr(0) . '[[\'تحذير: تم تحميل هذا الإيصال قبل ( مرات%1$d، عبر%2$s). تحقق منه قبل تأكيد الدفع.\', \'ar\']]',
  'Earlier donation: #%d.' => '\\nالتبرع السابق: #%d.\\n',
  'WooCommerce checkout' => '\\nالخروج من WooCommerce\\n',
  'You will choose how to pay (card or bank transfer) on the next page.' => '\\nسوف تختار كيفية الدفع (بالبطاقة أو التحويل البنكي) في الصفحة التالية.\\n',
  'Monthly donations are paid by card; the card is stored by iyzico and charged once a month.' => '\\nيتم دفع التبرعات الشهرية عن طريق البطاقة؛ يتم تخزين البطاقة بواسطة iyzico ويتم شحنها مرة واحدة في الشهر.\\n',
  'This form is not linked to a donation type. Please contact the site administrator.' => '\\nهذا النموذج غير مرتبط بنوع التبرع. الرجاء الاتصال بمسؤول الموقع.\\n',
  'The donation type of this form was not found.' => '\\nلم يتم العثور على نوع التبرع لهذا النموذج.\\n',
  'The amount could not be calculated. Please review your choices and try again.' => '\\nتعذر حساب المبلغ. الرجاء مراجعة اختياراتك والمحاولة مرة أخرى.\\n',
  'You have no pending donations.' => '\\nليس لديك أية تبرعات معلقة.\\n',
  'Donations made by bank transfer appear here until the payment is confirmed.' => '\\nتظهر هنا التبرعات المقدمة عن طريق التحويل المصرفي حتى يتم تأكيد الدفع.\\n',
  'Your bank transfer donations. If you have made the payment, upload your receipt; your certificate is sent once it is confirmed.' => '\\nتبرعاتك عن طريق التحويل البنكي. إذا قمت بالدفع، قم بتحميل الإيصال الخاص بك؛ سيتم إرسال شهادتك بمجرد تأكيدها.\\n',
  'Donation #%s' => '\\nالتبرع #%s\\n',
  '%s donation is awaiting payment' . chr(0) . '%s donations are awaiting payment' => '[[\'تبرعات%sفي انتظار الدفع\', \'ar\']]' . chr(0) . '[[\'التبرع بـ%sفي انتظار الدفع\', \'ar\']]' . chr(0) . '[[\'تبرعات%sفي انتظار الدفع\', \'ar\']]' . chr(0) . '[[\'تبرعات%sفي انتظار الدفع\', \'ar\']]' . chr(0) . '[[\'تبرعات%sفي انتظار الدفع\', \'ar\']]' . chr(0) . '[[\'تبرعات%sفي انتظار الدفع\', \'ar\']]',
  'If you have made the transfer, upload your receipt.' => '\\nإذا قمت بالتحويل، قم بتحميل الإيصال الخاص بك.\\n',
  'Please write your e-mail or phone number (at least one).' => '\\nالرجاء كتابة بريدك الإلكتروني أو رقم هاتفك (واحد على الأقل).\\n',
  'Write at least one. We send your receipt and certificate there.' => '\\nاكتب واحدة على الأقل. سنرسل الإيصال والشهادة إلى هناك.\\n',
  'Continue to payment' => '\\nمتابعة الدفع\\n',
  'I have read and accept the %1$sprivacy policy%2$s and the %3$sdonation agreement%4$s.' => '\\nلقد قرأت وقبلت سياسة خصوصية%1$s%2$sواتفاقية التبرع%3$s%4$s.\\n',
  'Make payment' => '\\nإجراء الدفع\\n',
  'Please read and accept the terms to continue.' => '\\nالرجاء قراءة الشروط وقبولها للمتابعة.\\n',
  'Donation terms' => '\\nشروط التبرع\\n',
  'Privacy policy' => '\\nسياسة الخصوصية\\n',
  'These terms apply to donations made on this site to %s.' => '\\nتنطبق هذه الشروط على التبرعات المقدمة على هذا الموقع إلى%s.\\n',
  'A donation is a gift without anything in return. It is used for the purpose chosen on the donation form (for example sapling planting). When a purpose is fully funded, the association may use the donation for a similar purpose.' => '\\nالتبرع هو هدية بدون أي مقابل. يتم استخدامه للغرض المختار في نموذج التبرع (على سبيل المثال زراعة الشتلات). عندما يتم تمويل غرض ما بالكامل، يجوز للجمعية استخدام التبرع لغرض مماثل.\\n',
  'Card payments are processed by the licensed payment institution iyzico with 3D Secure. Card details are not stored on this site. For bank transfers, the donation is confirmed when the money reaches the association account.' => '\\nتتم معالجة مدفوعات البطاقة بواسطة مؤسسة الدفع المرخصة iyzico باستخدام 3D Secure. لا يتم تخزين تفاصيل البطاقة على هذا الموقع. بالنسبة للتحويلات البنكية، يتم تأكيد التبرع عندما تصل الأموال إلى حساب الجمعية.\\n',
  'A monthly donation is charged to the same card every month until you cancel it. You can cancel it at any time from your account page or by writing to us.' => '\\nيتم تحصيل التبرع الشهري من نفس البطاقة كل شهر حتى تقوم بإلغائه. ويمكنك إلغاؤه في أي وقت من صفحة حسابك أو عن طريق مراسلتنا.\\n',
  'The online certificate is sent to the e-mail address or phone number you give after the payment is confirmed. Please check the names you write on the certificate.' => '\\nيتم إرسال الشهادة عبر الإنترنت إلى عنوان البريد الإلكتروني أو رقم الهاتف الذي تقدمه بعد تأكيد الدفع. الرجاء التحقق من الأسماء التي تكتبها على الشهادة.\\n',
  'Cancellation and refunds' => '\\nالإلغاء واسترداد الأموال\\n',
  'If a donation was made by mistake (wrong amount or a double payment), write to us within 14 days and it is refunded to the same card or account.' => '\\nإذا تم التبرع عن طريق الخطأ (مبلغ خاطئ أو دفعة مضاعفة)، فاكتب إلينا خلال 14 يومًا وسيتم رده إلى نفس البطاقة أو الحساب.\\n',
  'Your name and contact details are used to record the donation, send the receipt and certificate, and contact you about your donation. See the privacy policy for details.' => '\\nيتم استخدام اسمك وتفاصيل الاتصال الخاصة بك لتسجيل التبرع وإرسال الإيصال والشهادة والاتصال بك بخصوص تبرعك. راجع سياسة الخصوصية للحصول على التفاصيل.\\n',
  'For any question about your donation, write to us on WhatsApp: %s' => '\\nإذا كان لديك أي سؤال حول تبرعك، راسلنا على WhatsApp:%s\\n',
  'For any question about your donation, write to us through the contact page.' => '\\nإذا كان لديك أي سؤال حول تبرعك، راسلنا عبر صفحة الاتصال.\\n',
  '%s processes your personal data under the Turkish Personal Data Protection Law (KVKK).' => '\\n تعالج%sبياناتك الشخصية بموجب قانون حماية البيانات الشخصية التركي (KVKK).\\n',
  'What we collect' => '\\nما نقوم بجمعه\\n',
  'Name, e-mail address, phone number and the details of your donation. Card details are entered on the payment institution and are not stored by us.' => '\\nالاسم وعنوان البريد الإلكتروني ورقم الهاتف وتفاصيل تبرعك. يتم إدخال تفاصيل البطاقة في مؤسسة الدفع ولا نقوم بتخزينها.\\n',
  'To record donations, send receipts and certificates, meet legal obligations and answer your questions.' => '\\nلتسجيل التبرعات وإرسال الإيصالات والشهادات والوفاء بالالتزامات القانونية والإجابة على أسئلتك.\\n',
  'Your rights' => '\\nحقوقك\\n',
  'You can ask what data we hold about you, have it corrected or deleted, by writing to us.' => '\\nيمكنك الاستفسار عن البيانات التي نحتفظ بها عنك، أو تصحيحها أو حذفها، عن طريق الكتابة إلينا.\\n',
  'Block checkout' => '\\nحظر الخروج\\n',
  'No address' => '\\nلا يوجد عنوان\\n',
  'Server check' => '\\nفحص الخادم\\n',
